-- +goose Up
-- Gokku initial schema (SQLite via modernc.org/sqlite).
--
-- Conventions
--   * ids are TEXT (ULID, generated by the application) unless stated otherwise.
--   * timestamps are TEXT, UTC, RFC 3339 with milliseconds. They sort lexicographically.
--   * Dokku is the source of truth for apps, services, config and domains.
--     This database only stores Gokku's own state: users, sessions, projects and
--     their membership, shared variables, jobs, deploy history and the audit log.
--   * Foreign keys are enforced per connection: open the database with
--     _pragma=foreign_keys(1) (see DESIGN.md, "Database").
--   * Names that mirror Dokku identifiers (app, service) carry no foreign key,
--     because Dokku can create or destroy them outside Gokku. The reconciler
--     prunes rows whose Dokku object no longer exists.

-- ---------------------------------------------------------------------------
-- Users, sessions, tokens
-- ---------------------------------------------------------------------------

CREATE TABLE users (
    id                  TEXT PRIMARY KEY,
    username            TEXT NOT NULL UNIQUE COLLATE NOCASE,
    password_hash       TEXT,                                   -- argon2id; NULL while status = 'invited'
    role                TEXT NOT NULL DEFAULT 'viewer',
    status              TEXT NOT NULL DEFAULT 'active',
    theme               TEXT NOT NULL DEFAULT 'system',         -- per-user preference, edited from the account menu
    invite_token_hash   TEXT,                                   -- sha256 hex of the one-time invite token
    invite_expires_at   TEXT,
    password_changed_at TEXT,
    last_login_at       TEXT,
    created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    CHECK (role IN ('viewer', 'operator', 'admin')),
    CHECK (status IN ('active', 'invited', 'disabled')),
    CHECK (theme IN ('system', 'light', 'dark')),
    -- 3 to 32 chars, lowercase letters, digits, dash, underscore; starts with a letter or digit.
    CHECK (length(username) BETWEEN 3 AND 32),
    CHECK (username = lower(username)),
    CHECK (username GLOB '[a-z0-9]*'),
    CHECK (username NOT GLOB '*[^a-z0-9_-]*'),
    CHECK (status <> 'active' OR password_hash IS NOT NULL)
);

-- Never leave the system without an active admin.
-- +goose StatementBegin
CREATE TRIGGER users_keep_admin_on_update
BEFORE UPDATE OF role, status ON users
WHEN OLD.role = 'admin' AND OLD.status = 'active'
     AND (NEW.role <> 'admin' OR NEW.status <> 'active')
BEGIN
    SELECT RAISE(ABORT, 'at least one active admin is required')
    WHERE (SELECT COUNT(*) FROM users
           WHERE role = 'admin' AND status = 'active' AND id <> OLD.id) = 0;
END;
-- +goose StatementEnd

-- +goose StatementBegin
CREATE TRIGGER users_keep_admin_on_delete
BEFORE DELETE ON users
WHEN OLD.role = 'admin' AND OLD.status = 'active'
BEGIN
    SELECT RAISE(ABORT, 'at least one active admin is required')
    WHERE (SELECT COUNT(*) FROM users
           WHERE role = 'admin' AND status = 'active' AND id <> OLD.id) = 0;
END;
-- +goose StatementEnd

CREATE TABLE sessions (
    id           TEXT PRIMARY KEY,                              -- sha256 hex of the session cookie value
    user_id      TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    last_seen_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    expires_at   TEXT NOT NULL,
    user_agent   TEXT NOT NULL DEFAULT '',
    ip           TEXT NOT NULL DEFAULT ''
);
CREATE INDEX idx_sessions_user    ON sessions (user_id);
CREATE INDEX idx_sessions_expires ON sessions (expires_at);

CREATE TABLE api_tokens (
    id           TEXT PRIMARY KEY,
    user_id      TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name         TEXT NOT NULL,
    token_hash   TEXT NOT NULL UNIQUE,                          -- sha256 hex; the plaintext is shown once
    token_prefix TEXT NOT NULL,                                 -- first characters, for display
    role         TEXT NOT NULL DEFAULT 'viewer',                -- capped at the owner's role when checked
    created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    last_used_at TEXT,
    expires_at   TEXT,
    revoked_at   TEXT,
    UNIQUE (user_id, name),
    CHECK (role IN ('viewer', 'operator', 'admin')),
    CHECK (length(name) BETWEEN 1 AND 64)
);
CREATE INDEX idx_api_tokens_user ON api_tokens (user_id);

-- ---------------------------------------------------------------------------
-- Projects: Gokku-side grouping of Dokku apps and services
-- ---------------------------------------------------------------------------

CREATE TABLE projects (
    id          TEXT PRIMARY KEY,
    slug        TEXT NOT NULL UNIQUE COLLATE NOCASE,
    name        TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    created_by  TEXT REFERENCES users (id) ON DELETE SET NULL,
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    CHECK (length(slug) BETWEEN 1 AND 40),
    CHECK (slug = lower(slug)),
    CHECK (slug GLOB '[a-z0-9]*'),
    CHECK (slug NOT GLOB '*[^a-z0-9-]*'),
    CHECK (length(name) BETWEEN 1 AND 80)
);

-- An app belongs to at most one project, hence app_name is the primary key.
CREATE TABLE project_apps (
    app_name   TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    added_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    CHECK (app_name GLOB '[a-z0-9]*'),
    CHECK (app_name NOT GLOB '*[^a-z0-9_-]*')
);
CREATE INDEX idx_project_apps_project ON project_apps (project_id);

-- A service belongs to at most one project. Links between apps and services are
-- NOT stored here: Dokku owns them and Gokku reads them (for example postgres:links).
CREATE TABLE project_services (
    service_type TEXT NOT NULL,                                 -- the Dokku plugin name, e.g. postgres, redis
    service_name TEXT NOT NULL,
    project_id   TEXT NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    added_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    PRIMARY KEY (service_type, service_name),
    CHECK (service_type GLOB '[a-z]*'),
    CHECK (service_type NOT GLOB '*[^a-z0-9]*'),
    CHECK (service_name GLOB '[a-z0-9]*'),
    CHECK (service_name NOT GLOB '*[^a-z0-9_-]*')
);
CREATE INDEX idx_project_services_project ON project_services (project_id);

-- Shared variables. Dokku has one env namespace per app, so these are written into
-- each member app's Dokku config by the reconciler; see SPEC.md, "Shared variables".
CREATE TABLE project_env (
    project_id TEXT NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    key        TEXT NOT NULL,
    value_enc  BLOB NOT NULL,                                   -- 1 version byte, 12 byte nonce, AES-256-GCM ciphertext
    is_secret  INTEGER NOT NULL DEFAULT 0,
    updated_by TEXT REFERENCES users (id) ON DELETE SET NULL,
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    PRIMARY KEY (project_id, key),
    CHECK (is_secret IN (0, 1)),
    CHECK (length(key) BETWEEN 1 AND 128),
    CHECK (key NOT GLOB '*[^A-Z0-9_]*'),
    CHECK (key NOT GLOB '[0-9]*')
);

-- Provenance: which keys on which apps were written by a project, and with which value.
-- A key is "managed" while its row exists here AND the app's current value hash matches.
-- If an app changes a managed key, the row is deleted and the key becomes an override.
CREATE TABLE project_env_applied (
    app_name   TEXT NOT NULL,
    key        TEXT NOT NULL,
    project_id TEXT NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    value_hash TEXT NOT NULL,                                   -- sha256 hex of the value that was written
    applied_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    PRIMARY KEY (app_name, key)
);
CREATE INDEX idx_project_env_applied_project ON project_env_applied (project_id);

-- ---------------------------------------------------------------------------
-- Jobs: long-running work with streamed output
-- ---------------------------------------------------------------------------

CREATE TABLE jobs (
    id          TEXT PRIMARY KEY,
    kind        TEXT NOT NULL,                                  -- e.g. app.restart, app.rebuild, deploy.image, project.rebuild_all
    title       TEXT NOT NULL,
    status      TEXT NOT NULL DEFAULT 'queued',
    parent_id   TEXT REFERENCES jobs (id) ON DELETE CASCADE,    -- project actions fan out into one child job per app
    project_id  TEXT REFERENCES projects (id) ON DELETE SET NULL,
    app_name    TEXT,
    created_by  TEXT REFERENCES users (id) ON DELETE SET NULL,
    source      TEXT NOT NULL DEFAULT 'web',
    error       TEXT,                                           -- short failure summary, no secrets
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    started_at  TEXT,
    finished_at TEXT,
    CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'canceled')),
    CHECK (source IN ('web', 'api', 'system'))
);
CREATE INDEX idx_jobs_status       ON jobs (status);
CREATE INDEX idx_jobs_parent       ON jobs (parent_id);
CREATE INDEX idx_jobs_project_time ON jobs (project_id, created_at DESC);
CREATE INDEX idx_jobs_app_time     ON jobs (app_name, created_at DESC);

CREATE TABLE job_steps (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    job_id      TEXT NOT NULL REFERENCES jobs (id) ON DELETE CASCADE,
    position    INTEGER NOT NULL,
    name        TEXT NOT NULL,
    status      TEXT NOT NULL DEFAULT 'queued',
    started_at  TEXT,
    finished_at TEXT,
    UNIQUE (job_id, position),
    CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'skipped', 'canceled'))
);

-- Output is stored line by line so streams can resume with Last-Event-ID = seq.
CREATE TABLE job_logs (
    job_id  TEXT NOT NULL REFERENCES jobs (id) ON DELETE CASCADE,
    seq     INTEGER NOT NULL,
    step_id INTEGER REFERENCES job_steps (id) ON DELETE SET NULL,
    ts      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    stream  TEXT NOT NULL DEFAULT 'stdout',
    line    TEXT NOT NULL,
    PRIMARY KEY (job_id, seq),
    CHECK (stream IN ('stdout', 'stderr', 'system'))
);

-- Deployment history shown on the app Deploy tab. A row exists for every deploy Gokku
-- started (job_id set) and for deploys it only observed, such as a git push, by seeing
-- the deployed revision change in the snapshot (job_id NULL, no output available).
CREATE TABLE deploys (
    id          TEXT PRIMARY KEY,
    app_name    TEXT NOT NULL,
    source      TEXT NOT NULL,
    ref         TEXT NOT NULL DEFAULT '',                       -- commit sha, image reference or branch
    status      TEXT NOT NULL,
    job_id      TEXT REFERENCES jobs (id) ON DELETE SET NULL,
    created_by  TEXT REFERENCES users (id) ON DELETE SET NULL,
    started_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    finished_at TEXT,
    CHECK (source IN ('git', 'image', 'repository', 'rebuild', 'observed')),
    CHECK (status IN ('running', 'succeeded', 'failed', 'canceled'))
);
CREATE INDEX idx_deploys_app_time ON deploys (app_name, started_at DESC);

-- ---------------------------------------------------------------------------
-- Audit log
-- ---------------------------------------------------------------------------

-- Append-only. Actor and target names are snapshots on purpose, so entries stay
-- readable after a user, project or app is renamed or deleted. No foreign keys.
CREATE TABLE audit_log (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    ts           TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    actor_type   TEXT NOT NULL,
    actor_id     TEXT,
    actor_name   TEXT NOT NULL,
    action       TEXT NOT NULL,                                 -- e.g. apps:restart, config:set, users:update
    target_type  TEXT NOT NULL DEFAULT '',
    target_name  TEXT NOT NULL DEFAULT '',
    project_slug TEXT NOT NULL DEFAULT '',
    result       TEXT NOT NULL,
    source       TEXT NOT NULL,
    job_id       TEXT,
    detail       TEXT NOT NULL DEFAULT '{}',                    -- JSON; secret values are never written here
    CHECK (actor_type IN ('user', 'token', 'system', 'git')),
    CHECK (result IN ('ok', 'fail')),
    CHECK (source IN ('web', 'api', 'git', 'system')),
    CHECK (json_valid(detail))
);
CREATE INDEX idx_audit_ts      ON audit_log (ts DESC);
CREATE INDEX idx_audit_actor   ON audit_log (actor_name, ts DESC);
CREATE INDEX idx_audit_project ON audit_log (project_slug, ts DESC);
CREATE INDEX idx_audit_target  ON audit_log (target_type, target_name, ts DESC);

-- ---------------------------------------------------------------------------
-- Instance settings (small key/value store)
-- ---------------------------------------------------------------------------

-- Known keys: setup_complete ('1' after the first admin exists), session_lifetime_hours,
-- min_password_length, secret_key_fingerprint, job_retention_days, protected_apps (JSON array of app names).
CREATE TABLE settings (
    key        TEXT PRIMARY KEY,
    value      TEXT NOT NULL,
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- +goose Down
DROP TABLE IF EXISTS settings;
DROP TABLE IF EXISTS audit_log;
DROP TABLE IF EXISTS deploys;
DROP TABLE IF EXISTS job_logs;
DROP TABLE IF EXISTS job_steps;
DROP TABLE IF EXISTS jobs;
DROP TABLE IF EXISTS project_env_applied;
DROP TABLE IF EXISTS project_env;
DROP TABLE IF EXISTS project_services;
DROP TABLE IF EXISTS project_apps;
DROP TABLE IF EXISTS projects;
DROP TABLE IF EXISTS api_tokens;
DROP TABLE IF EXISTS sessions;
DROP TRIGGER IF EXISTS users_keep_admin_on_delete;
DROP TRIGGER IF EXISTS users_keep_admin_on_update;
DROP TABLE IF EXISTS users;
